import useSWR from 'swr';
import { requestJson } from '../util/apiClient';

type UsersFilters = {
  search?: string;
  userType?: string;
  role?: string;
  serverId?: string;
  filterType?: string;
  searchEmail?: string;
  searchUsername?: string;
  searchNotes?: string;
  sort?: string;
  page?: number;
  pageSize?: number;
};

type UsersResponse = {
  data: Array<{
    uuid: string;
    username?: string;
    email?: string;
    external_email?: string;
    user_type: string;
    display_name?: string;
    avatar_url?: string | null;
    created_at?: string;
    last_streamed_at?: string | null;
    service_join_date?: string | null;
    last_login_at?: string;
    last_platform?: string | null;
    last_player?: string | null;
    last_known_ip?: string | null;
    total_plays?: number;
    total_duration?: number;
    last_played?: {
      media_title?: string | null;
      original_media_title?: string | null;
      media_type?: string | null;
      grandparent_title?: string | null;
      parent_title?: string | null;
      rating_key?: string | null;
      server_id?: number | null;
      thumb_url?: string | null;
      started_at?: string | null;
    } | null;
    is_active: boolean;
    admin_roles: string[];
    user_roles: Array<{
      name: string;
      color?: string | null;
      description?: string | null;
      icon?: string | null;
    }>;
    linked_service_count: number;
    service_type?: string;
    server_nickname?: string;
    libraries?: string[];
    has_all_libraries?: boolean;
    access_expires_at?: string | null;
    linked_local_user?: {
      uuid: string;
      username?: string | null;
      display_name?: string | null;
    } | null;
    notes?: string | null;
  }>;
  meta: {
    pagination: {
      page: number;
      page_size: number;
      total_items: number;
      total_pages: number;
    };
  };
};

export const useUsersPaginated = (filters: UsersFilters = {}) => {
  const page = filters.page || 1;
  const pageSize = filters.pageSize || 50;

  const params = new URLSearchParams({
    page: String(page),
    page_size: String(pageSize)
  });

  if (filters.search) params.set('search', filters.search);
  if (filters.userType) params.set('user_type', filters.userType);
  if (filters.role) params.set('role', filters.role);
  // Include extended filters supported by our v2 implementation
  if (filters.serverId && filters.serverId !== 'all') params.set('server_id', filters.serverId);
  if (filters.filterType) params.set('filter_type', filters.filterType);
  if (filters.searchEmail) params.set('search_email', filters.searchEmail);
  if (filters.searchUsername) params.set('search_username', filters.searchUsername);
  if (filters.searchNotes) params.set('search_notes', filters.searchNotes);
  if (filters.sort) params.set('sort', filters.sort);

  const { data, error, isLoading, mutate } = useSWR<UsersResponse>(
    `/api/v2/users?${params.toString()}`,
    (url: string) => requestJson<UsersResponse>(url),
    {
      revalidateOnFocus: false
    }
  );

  return {
    users: data?.data || [],
    pagination: data?.meta.pagination,
    error,
    loading: isLoading,
    mutate
  };
};
